const XS=[0.8,1.5,2.1,2.9,3.6,4.4,5.2,6.0,6.7,7.5,8.3,9.2];
const CL=[0,0,0,1,0,0,1,0,1,1,1,1];
const N=XS.length;
function imp(a,b,m){const n=a+b;if(!n)return 0;const p=a/n,q=b/n;if(m==='gini')return 1-p*p-q*q;let h=0;if(p>0)h-=p*Math.log(p)/Math.LN2;if(q>0)h-=q*Math.log(q)/Math.LN2;return h;}
function split(c,m){let la=0,lb=0,ra=0,rb=0;for(let i=0;i<N;i++){if(XS[i]<c){if(CL[i])lb++;else la++;}else{if(CL[i])rb++;else ra++;}}const nl=la+lb,nr=ra+rb;const il=imp(la,lb,m),ir=imp(ra,rb,m);return {la,lb,ra,rb,nl,nr,il,ir,w:(nl*il+nr*ir)/N};}
export function initialState(){return {revealed:false};}
export function reduce({state,event}){if(event.type==='action'){if(event.action==='reveal')return {revealed:true};if(event.action==='hide')return {revealed:false};}return state;}
export function evaluate({inputs,state}){
const m=inputs.measure==='entropy'?'entropy':'gini';
const cut=sdk.clamp(Number(inputs.cutoff),0.5,9.5);
const revealed=!!(state&&state.revealed);
const X=v=>60+v*54;
const s=split(cut,m);
const parent=imp(6,6,m);
const gain=parent-s.w;
let best=null,bw=Infinity;
for(let i=0;i<N-1;i++){const c=(XS[i]+XS[i+1])/2;const r=split(c,m);if(r.w<bw-1e-12){bw=r.w;best=c;}}
const o=[];
o.push(sdk.text('title',30,30,'Where should the tree split? Move the cutoff, then compare with the best.'));
o.push(sdk.text('legend',30,58,'Each circle is one point: A (class A) or B (class B).'));
o.push(sdk.line('axis',X(0),150,X(10),150));
o.push(sdk.text('ax0',X(0),182,'0',{align:'middle'}));
o.push(sdk.text('ax10',X(10),182,'10',{align:'middle'}));
for(let i=0;i<N;i++){o.push(sdk.circle('p'+i,X(XS[i]),150,22,{text:CL[i]?'B':'A',role:CL[i]?'prediction':'input'}));}
const cx=X(cut);
o.push(sdk.line('cut',cx,110,cx,190,{role:'learner'}));
o.push(sdk.text('cutlabel',sdk.clamp(cx,110,550),100,'your cutoff x = '+sdk.format(cut,1),{align:'middle',role:'learner'}));
if(revealed){const bx=X(best);o.push(sdk.line('bestline',bx,118,bx,196,{role:'success',opacity:0.8}));o.push(sdk.text('bestlabel',sdk.clamp(bx,110,550),212,'best cutoff x = '+sdk.format(best,2),{align:'middle',role:'success'}));}
const px=640;
o.push(sdk.text('meas',px,80,'Measure: '+(m==='gini'?'Gini impurity':'Entropy (bits)')));
o.push(sdk.math('formI',px,108,m==='gini'?'I = 1 - \\sum_k p_k^2':'I = -\\sum_k p_k \\log_2 p_k'));
o.push(sdk.text('left',px,148,'Left side: '+s.la+' A, '+s.lb+' B  (n = '+s.nl+')'));
o.push({kind:'text',id:'leftI',x:px+20,y:170,runs:[{kind:'text',text:'impurity '},{kind:'math',tex:'I_L'},{kind:'text',text:' = '+sdk.format(s.il,3)}]});
o.push(sdk.text('right',px,198,'Right side: '+s.ra+' A, '+s.rb+' B  (n = '+s.nr+')'));
o.push({kind:'text',id:'rightI',x:px+20,y:220,runs:[{kind:'text',text:'impurity '},{kind:'math',tex:'I_R'},{kind:'text',text:' = '+sdk.format(s.ir,3)}]});
o.push(sdk.math('formW',px,256,'W = \\tfrac{n_L}{n} I_L + \\tfrac{n_R}{n} I_R'));
o.push(sdk.text('wval',px,290,'Weighted impurity W = '+sdk.format(s.w,3)));
o.push(sdk.text('pval',px,314,'Unsplit set (6 A, 6 B): '+sdk.format(parent,3)));
o.push(sdk.text('gval',px,338,'Impurity removed = '+sdk.format(gain,3),{role:'learner'}));
if(revealed){o.push(sdk.text('cmp1',px,374,'Best: W = '+sdk.format(bw,3)+', removes '+sdk.format(parent-bw,3),{role:'success'}));
const diff=s.w-bw;o.push(sdk.text('cmp2',px,398,diff<1e-9?'Your cutoff is as good as the best.':'Yours leaves '+sdk.format(diff,3)+' more impurity.'));}
else{o.push(sdk.text('cmp1',px,374,'Press "Reveal best split" to compare.'));}
o.push(sdk.text('note',px,440,'Lower W = purer sides, weighted by size.'));
if(revealed){
const PX=X;const ymax=parent*1.1;const PY=w=>500-w/ymax*210;
const b=[0.5].concat(XS,[9.5]);const pts=[];
for(let k=0;k<b.length-1;k++){const w=split((b[k]+b[k+1])/2,m).w;pts.push([PX(b[k]),PY(w)]);pts.push([PX(b[k+1]),PY(w)]);}
o.push(sdk.line('pxaxis',PX(0),500,PX(10),500));
o.push(sdk.line('pyaxis',PX(0),500,PX(0),PY(ymax)));
o.push(sdk.text('pylabel',PX(0)+8,PY(ymax)-6,'weighted impurity W (top = '+sdk.format(ymax,2)+')'));
o.push(sdk.text('px0',PX(0),518,'0',{align:'middle'}));
o.push(sdk.text('px10',PX(10),518,'10',{align:'middle'}));
o.push(sdk.text('pxlabel',PX(5),532,'cutoff x',{align:'middle'}));
o.push(sdk.line('pparent',PX(0),PY(parent),PX(10),PY(parent),{opacity:0.4}));
o.push(sdk.polyline('curve',pts,{role:'neutral'}));
o.push(sdk.circle('bestpt',PX(best),PY(bw),14,{role:'success'}));
o.push(sdk.text('bestpttxt',PX(best),PY(bw)+24,'best',{align:'middle',role:'success'}));
o.push(sdk.circle('youpt',PX(cut),PY(s.w),10,{role:'learner'}));
}
else{o.push(sdk.text('hint',320,390,'The curve of W for every cutoff appears after Reveal.',{align:'middle'}));}
return {frame:{width:960,height:540,objects:o,readouts:[{id:'weighted',value:s.w},{id:'gain',value:gain},{id:'parentImp',value:parent}]},quantities:{cutoff:cut,weighted:s.w,gain:gain,parent:parent,best:best,bestW:bw}};
}

